//! Golden test: codecs (accept/reject), `min`/`max` and 40-sample sequences of every Int/Float/Height
//! provider type against the vanilla classes (fixture generated by `tests/oracle/ProviderOracle.java`).

use std::panic::{AssertUnwindSafe, catch_unwind};

use mc_core::random::{LegacyRandomSource, RandomSource, XoroshiroRandomSource};
use mc_worldgen::provider::{FloatProvider, HeightProvider, IntProvider};
use mc_worldgen::world_generation_context::WorldGenerationContext;

const SPECS: [(u8, i64); 3] = [(0, 0), (0, 12345), (1, 42)];
const SAMPLES: usize = 40;
const CONTEXTS: [(i32, i32, i32); 3] = [(-64, 384, 63), (0, 128, 32), (-32, 112, 10)];

fn rng(kind: u8, seed: i64) -> Box<dyn RandomSource> {
    if kind == 0 {
        Box::new(LegacyRandomSource::new(seed))
    } else {
        Box::new(XoroshiroRandomSource::new(seed))
    }
}

/// The oracle's `run`: samples joined by `,`, then `L<next long>`, or `X` where vanilla threw.
fn run(kind: u8, seed: i64, mut sample: impl FnMut(&mut dyn RandomSource) -> String) -> String {
    let mut random = rng(kind, seed);
    let mut out = String::new();
    for _ in 0..SAMPLES {
        match catch_unwind(AssertUnwindSafe(|| sample(random.as_mut()))) {
            Ok(value) => {
                out.push_str(&value);
                out.push(',');
            }
            Err(_) => {
                out.push('X');
                return out;
            }
        }
    }
    out.push_str(&format!("L{}", random.next_long()));
    out
}

fn bits(f: f32) -> String {
    format!("{:08x}", f.to_bits())
}

fn int_range(kind: &str) -> Option<(i32, i32)> {
    let mut parts = kind.strip_prefix("int_r:")?.split(':');
    Some((parts.next()?.parse().ok()?, parts.next()?.parse().ok()?))
}

#[test]
fn providers_match_vanilla() {
    let fixture = mc_testkit::include_gz!("../fixtures/providers.txt.gz");
    let mut ok_cases = 0;
    let mut err_cases = 0;
    let mut sampled = 0;
    for (line_no, line) in fixture.lines().enumerate() {
        let mut fields = line.split('\t');
        let (kind, json, status) = (
            fields.next().unwrap(),
            fields.next().unwrap(),
            fields.next().unwrap(),
        );
        let value: serde_json::Value = serde_json::from_str(json).unwrap();
        let ctx = format!("line {}: {kind} {json}", line_no + 1);
        let expected: Vec<&str> = fields.collect();
        let mut actual: Vec<String> = Vec::new();

        let parsed: Result<(), String> = match kind {
            "int" | "int_nn" | "int_pos" => {
                let result = match kind {
                    "int" => IntProvider::from_json(&value),
                    "int_nn" => IntProvider::non_negative_from_json(&value),
                    _ => IntProvider::positive_from_json(&value),
                };
                int_case(result, &mut actual)
            }
            k if k.starts_with("int_r:") => {
                let (min, max) = int_range(k).unwrap();
                int_case(IntProvider::from_json_range(&value, min, max), &mut actual)
            }
            "float" => float_case(FloatProvider::from_json(&value), &mut actual),
            "float_min:0.0" => float_case(FloatProvider::from_json_min(&value, 0.0), &mut actual),
            "float_r:-1.0:1.0" => float_case(
                FloatProvider::from_json_range(&value, -1.0, 1.0),
                &mut actual,
            ),
            "height" => match HeightProvider::from_json(&value) {
                Ok(p) => {
                    for (min_y, height, sea) in CONTEXTS {
                        let context = WorldGenerationContext::of_level(min_y, height, sea);
                        for (kind, seed) in SPECS {
                            actual.push(format!(
                                "h{min_y}_{kind}_{seed}={}",
                                run(kind, seed, |r| p.sample(r, &context).to_string())
                            ));
                        }
                    }
                    Ok(())
                }
                Err(e) => Err(e.to_string()),
            },
            other => panic!("unknown kind {other}"),
        };
        match (status, parsed) {
            ("OK", Ok(())) => {
                ok_cases += 1;
                assert_eq!(actual, expected, "{ctx}");
                sampled += actual.len();
            }
            ("ERR", Err(_)) => err_cases += 1,
            ("OK", Err(e)) => panic!("{ctx}: vanilla accepts, we reject: {e}"),
            ("ERR", Ok(())) => panic!("{ctx}: vanilla rejects, we accept"),
            _ => unreachable!(),
        }
    }
    // The fixture must exercise both outcomes and plenty of sample sequences.
    assert!(
        ok_cases > 500 && err_cases > 100 && sampled > 3000,
        "{ok_cases} {err_cases} {sampled}"
    );
}

fn int_case(
    result: Result<IntProvider, mc_worldgen::data::LoadError>,
    actual: &mut Vec<String>,
) -> Result<(), String> {
    let p = result.map_err(|e| e.to_string())?;
    actual.push(format!("{} {}", p.min_inclusive(), p.max_inclusive()));
    for (kind, seed) in SPECS {
        actual.push(format!(
            "i{kind}_{seed}={}",
            run(kind, seed, |r| p.sample(r).to_string())
        ));
    }
    Ok(())
}

fn float_case(
    result: Result<FloatProvider, mc_worldgen::data::LoadError>,
    actual: &mut Vec<String>,
) -> Result<(), String> {
    let p = result.map_err(|e| e.to_string())?;
    actual.push(format!("{} {}", bits(p.min()), bits(p.max())));
    for (kind, seed) in SPECS {
        actual.push(format!(
            "f{kind}_{seed}={}",
            run(kind, seed, |r| bits(p.sample(r)))
        ));
    }
    Ok(())
}
